import unittest

from blog import make_url, slugify
from textutil import slugify as raw_slugify


class TestBlog(unittest.TestCase):
    def test_slugify(self):
        self.assertEqual(slugify('Hello World'), 'hello-world')

    def test_url(self):
        self.assertEqual(make_url('Hello World'), '/posts/hello-world')

    def test_moved(self):
        self.assertEqual(raw_slugify('A B C'), 'a-b-c')


if __name__ == '__main__':
    unittest.main()
